fixture.testSource:
package helpers

import "testing"

func TestGeneratedProfile(t *testing.T) {
    profile := NewProfile("初始😀", 2)
    if profile.GetName() != "初始😀" || profile.GetCount() != 2 { t.Fatalf("constructor: %#v", profile) }
    profile.SetName("改后中文😀")
    profile.SetCount(7)
    if profile.GetName() != "改后中文😀" || profile.GetCount() != 7 { t.Fatalf("setters did not write back: %#v", profile) }
    var reader interface { GetName() string; GetCount() int } = profile
    if reader.GetName() != "改后中文😀" || reader.GetCount() != 7 { t.Fatal("value receiver method set failed") }
    t.Logf("name=%s count=%d value-method-set=pass", profile.GetName(), profile.GetCount())
}
